def transform(g):
    H=len(g); W=len(g[0])
    seed=[(r,c) for r in range(H) for c in range(W) if g[r][c]==2]
    bg=0
    other=set(g[r][c] for r in range(H) for c in range(W))-{2,bg}
    obstacle=other.pop() if other else None
    if not seed: return [row[:] for row in g]
    rel=[(r-seed[0][0], c-seed[0][1]) for r,c in seed]
    out=[row[:] for row in g]
    for tr in range(H):
        for tc in range(W):
            cells=[(tr+dr,tc+dc) for dr,dc in rel]
            if all(0<=r<H and 0<=c<W and g[r][c]==bg for r,c in cells):
                for r,c in cells: out[r][c]=2
    return out
